                log.debug(file.getName() + "," + file.getSize());
                FileOutputStream output = new FileOutputStream(localDirectory + file.getName());
                try {
                    ftp.retrieveFile(file.getName(), output);
                } finally {
                    IOUtils.closeQuietly(output);
                }
            }
        }
    } catch (Exception e) {
        throw new DataSyncException(e);
    } finally {
        try {
            ftp.disconnect();
        } catch (IOException e) {
        }
    }
}

