    final char[] buffer = new char[1024 * 1024];
    StringBuilder out = new StringBuilder();
    Reader in = new InputStreamReader(openConnection.getInputStream(), "UTF-8");
    int read;
    do {
        read = in.read(buffer, 0, buffer.length);
        if (read > 0) {
