    System.out.println("copy " + source + " -> " + dest);
    FileInputStream in = new FileInputStream(source);
    try {
        FileOutputStream out = new FileOutputStream(dest);
        try {
            byte[] buf = new byte[1024];
            int len = 0;
            while ((len = in.read(buf)) > 0) out.write(buf, 0, len);
        } finally {
            out.close();
        }
    } finally {
        in.close();
    }
}

public static void copyFile(File src, File dest) throws IOException {
    log.debug("Copying file: '" + src + "' to '" + dest + "'");
    FileChannel srcChannel = new FileInputStream(src).getChannel();
    FileChannel dstChannel = new FileOutputStream(dest).getChannel();
    dstChannel.transferFrom(srcChannel, 0, srcChannel.size());
    srcChannel.close();
    dstChannel.close();
}

private static void addFolderToZip(File folder, ZipOutputStream zip, String baseName) throws IOException {
    File[] files = folder.listFiles();
    for (File file : files) {
        if (file.isDirectory()) {
            String name = file.getAbsolutePath().substring(baseName.length());
            ZipEntry zipEntry = new ZipEntry(name + "/");
            zip.putNextEntry(zipEntry);
            zip.closeEntry();
            addFolderToZip(file, zip, baseName);
        } else {
            String name = file.getAbsolutePath().substring(baseName.length());
            ZipEntry zipEntry = new ZipEntry(updateFilename(name));
            zip.putNextEntry(zipEntry);
            IOUtils.copy(new FileInputStream(file), zip);
            zip.closeEntry();
        }
    }
}

private String copyImageFile(String urlString, String filePath) {
    FileOutputStream destination = null;
    File destination_file = null;
    String inLine;
    String dest_name = "";
    byte[] buffer;
    int bytes_read;
    int last_offset = 0;
    int offset = 0;
    InputStream imageFile = null;
    try {
        URL url = new URL(urlString);
        imageFile = url.openStream();
        dest_name = url.getFile();
        offset = 0;
        last_offset = 0;
        offset = dest_name.indexOf('/', offset + 1);
        while (offset > -1) {
            last_offset = offset + 1;
            offset = dest_name.indexOf('/', offset + 1);
        }
        dest_name = filePath + File.separator + dest_name.substring(last_offset);
        destination_file = new File(dest_name);
        if (destination_file.exists()) {
            if (destination_file.isFile()) {
                if (!destination_file.canWrite()) {
                    System.out.println("FileCopy: destination " + "file is unwriteable: " + dest_name);
                }
                System.out.println("File " + dest_name + " already exists. File will be overwritten.");
            } else {
                System.out.println("FileCopy: destination " + "is not a file: " + dest_name);
            }
        } else {
            File parentdir = parent(destination_file);
            if (!parentdir.exists()) {
                System.out.println("FileCopy: destination " + "directory doesn't exist: " + dest_name);
            }
            if (!parentdir.canWrite()) {
                System.out.println("FileCopy: destination " + "directory is unwriteable: " + dest_name);
            }
        }
        destination = new FileOutputStream(dest_name);
        buffer = new byte[1024];
        while (true) {
            bytes_read = imageFile.read(buffer);
            if (bytes_read == -1) break;
            destination.write(buffer, 0, bytes_read);
        }
    } catch (MalformedURLException ex) {
        System.out.println("Bad URL " + urlString);
    } catch (IOException ex) {
        System.out.println(" IO error: " + ex.getMessage());
    } finally {
        if (imageFile != null) {
            try {
                imageFile.close();
            } catch (IOException e) {
            }
        }
        if (destination != null) {
            try {
                destination.close();
            } catch (IOException e) {
            }
        }
    }
    return (dest_name);
}

public static boolean copy(File src, File dest) {
    boolean result = true;
    String files[] = null;
    if (src.isDirectory()) {
        files = src.list();
        result = dest.mkdir();
    } else {
        files = new String[1];
        files[0] = "";
    }
    if (files == null) {
        files = new String[0];
    }
    for (int i = 0; (i < files.length) && result; i++) {
        File fileSrc = new File(src, files[i]);
        File fileDest = new File(dest, files[i]);
        if (fileSrc.isDirectory()) {
            result = copy(fileSrc, fileDest);
        } else {
            FileChannel ic = null;
            FileChannel oc = null;
            try {
                ic = (new FileInputStream(fileSrc)).getChannel();
                oc = (new FileOutputStream(fileDest)).getChannel();
                ic.transferTo(0, ic.size(), oc);
            } catch (IOException e) {
                log.error(sm.getString("expandWar.copy", fileSrc, fileDest), e);
