public static String sendGetRequest(String endpoint, String requestParameters) {
    String result = null;
    if (endpoint.startsWith("http://")) {
        try {
            System.setProperty("java.net.useSystemProxies", "true");
            String urlStr = endpoint;
            if (requestParameters != null && requestParameters.length() > 0) {
                urlStr += "?" + requestParameters;
            }
            URL url = new URL(urlStr);
            URLConnection conn = url.openConnection();
            BufferedReader rd = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuffer sb = new StringBuffer();
            String line;
            while ((line = rd.readLine()) != null) {
                sb.append(line + "\n");
            }
            rd.close();
            result = sb.toString();
        } catch (Exception e) {
            DebuggerQueue.addDebug(HTTPClient.class.getName(), Level.ERROR, "Error during download url %s error: %s", endpoint, e.getMessage());
        }
    }
    return result;
}

public static void postData(Reader data, URL endpoint, Writer output) throws Exception {
    HttpURLConnection urlc = null;
    try {
        urlc = (HttpURLConnection) endpoint.openConnection();
        try {
            urlc.setRequestMethod("POST");
        } catch (ProtocolException e) {
            throw new Exception("Shouldn't happen: HttpURLConnection doesn't support POST??", e);
        }
        urlc.setDoOutput(true);
        urlc.setDoInput(true);
        urlc.setUseCaches(false);
        urlc.setAllowUserInteraction(false);
        urlc.setRequestProperty("Content-type", "text/xml; charset=" + "UTF-8");
        OutputStream out = urlc.getOutputStream();
        try {
            Writer writer = new OutputStreamWriter(out, "UTF-8");
            pipe(data, writer);
            writer.close();
        } catch (IOException e) {
            throw new Exception("IOException while posting data", e);
        } finally {
            if (out != null) out.close();
        }
        InputStream in = urlc.getInputStream();
        try {
            Reader reader = new InputStreamReader(in);
            pipe(reader, output);
            reader.close();
        } catch (IOException e) {
            throw new Exception("IOException while reading response", e);
        } finally {
            if (in != null) in.close();
        }
    } catch (IOException e) {
        throw new Exception("Connection error (is server running at " + endpoint + " ?): " + e);
    } finally {
        if (urlc != null) urlc.disconnect();
    }
}

public static void downloadFromUrl(URL url, String localFilename, String userAgent) throws IOException {
    InputStream is = null;
    FileOutputStream fos = null;
    System.setProperty("java.net.useSystemProxies", "true");
    try {
        URLConnection urlConn = url.openConnection();
        if (userAgent != null) {
            urlConn.setRequestProperty("User-Agent", userAgent);
        }
        is = urlConn.getInputStream();
        fos = new FileOutputStream(localFilename);
        byte[] buffer = new byte[4096];
        int len;
        while ((len = is.read(buffer)) > 0) {
            fos.write(buffer, 0, len);
        }
    } finally {
        try {
            if (is != null) {
                is.close();
            }
        } finally {
            if (fos != null) {
                fos.close();
            }
        }
    }
}

