        throw e;
    } finally {
        statement.close();
    }
}

private String buildShaHashOf(String source) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA");
        md.update(source.getBytes());
        return new BigInteger(1, md.digest()).toString(16);
    } catch (NoSuchAlgorithmException e) {
        e.printStackTrace();
        return "";
    }
}

public static boolean ejecutarDMLTransaccion(List<String> tirasSQL) throws Exception {
    boolean ok = true;
    try {
        getConexion();
        conexion.setAutoCommit(false);
        Statement st = conexion.createStatement();
        for (String cadenaSQL : tirasSQL) {
            if (st.executeUpdate(cadenaSQL) < 1) {
                ok = false;
                break;
            }
        }
        if (ok) conexion.commit(); else conexion.rollback();
        conexion.setAutoCommit(true);
        conexion.close();
    } catch (SQLException e) {
        if (conexion != null && !conexion.isClosed()) {
            conexion.rollback();
        }
        throw new Exception("Error en Transaccion");
    } catch (Exception e) {
        throw new Exception("Error en Transaccion");
    }
    return ok;
}

public static JSGFRuleGrammar newGrammarFromJSGF(URL url, JSGFRuleGrammarFactory factory) throws JSGFGrammarParseException, IOException {
