        return false;
    }
    if (this.isDirectory()) toFile = (FileUtility) (new File(this, fromFile.getName()));
    if (toFile.exists()) {
        if (!toFile.canWrite()) {
            abort("FileUtility: destination file is unwriteable: " + pathName);
            return false;
