private static void insertFiles(Connection con, File file) throws IOException {
    BufferedReader bf = new BufferedReader(new FileReader(file));
    String line = bf.readLine();
    while (line != null) {
        if (!line.startsWith(" ") && !line.startsWith("#")) {
            try {
                System.out.println("Exec: " + line);
                PreparedStatement prep = con.prepareStatement(line);
                prep.executeUpdate();
                prep.close();
                con.commit();
            } catch (Exception e) {
                e.printStackTrace();
                try {
                    con.rollback();
                } catch (SQLException e1) {
                    e1.printStackTrace();
                }
            }
        }
        line = bf.readLine();
    }
    bf.close();
}

String openUrlAsString(String address, int maxLines) {
    StringBuffer sb;
    try {
        URL url = new URL(address);
        InputStream in = url.openStream();
        BufferedReader br = new BufferedReader(new InputStreamReader(in));
        sb = new StringBuffer();
        int count = 0;
        String line;
        while ((line = br.readLine()) != null && count++ < maxLines) sb.append(line + "\n");
        in.close();
    } catch (IOException e) {
        sb = null;
    }
    return sb != null ? new String(sb) : null;
}

