private OSD downloadList() throws IOException, IllegalStateException, ParseException, URISyntaxException {
    OSD osd = null;
    HttpClient client = new DefaultHttpClient();
    HttpGet getMethod = new HttpGet(new URI(listUri));
    try {
        HttpResponse response = client.execute(getMethod);
        if (response.getStatusLine().getStatusCode() != HttpStatus.SC_OK) {
            throw new HttpResponseException(response.getStatusLine().getStatusCode(), response.getStatusLine().getReasonPhrase());
        }
        HttpEntity entity = response.getEntity();
        if (entity != null) {
            InputStream stream = entity.getContent();
            String charset = null;
            if (entity.getContentType() != null) {
                HeaderElement values[] = entity.getContentType().getElements();
                if (values.length > 0) {
                    NameValuePair param = values[0].getParameterByName("charset");
                    if (param != null) {
                        charset = param.getValue();
                    }
                }
            }
            if (charset == null) {
                charset = HTTP.DEFAULT_CONTENT_CHARSET;
            }
            osd = OSD.parse(stream, charset);
        }
    } finally {
        getMethod.abort();
    }
    return osd;
}

private static void copyContent(final File srcFile, final File dstFile, final boolean gzipContent) throws IOException {
    final File dstFolder = dstFile.getParentFile();
    dstFolder.mkdirs();
    if (!dstFolder.exists()) {
        throw new RuntimeException("Unable to create the folder " + dstFolder.getAbsolutePath());
    }
    final InputStream in = new FileInputStream(srcFile);
    OutputStream out = new FileOutputStream(dstFile);
    if (gzipContent) {
        out = new GZIPOutputStream(out);
    }
    try {
        final byte[] buffer = new byte[1024];
        int read;
        while ((read = in.read(buffer)) != -1) {
            out.write(buffer, 0, read);
        }
    } finally {
        in.close();
        out.close();
    }
}

