    StringBuffer sb = new StringBuffer();
    String myPackage = getPackageName(eb);
    sb.append("package " + myPackage + ";\n");
    sb.append("\n");
    DaoValuesGenerator valgen = new DaoValuesGenerator();
    String values_class_name = valgen.getClassName(entity);
