        md.reset();
        md.update(username.getBytes());
        md.update(password.getBytes());
        byte[] rawhash = md.digest();
        output = byteToBase64(rawhash);
    } catch (Exception e) {
        throw new PersistenceException("error, could not generate password");
    }
    return output;
}

