        urlObj = new URL(url);
    } catch (MalformedURLException urlEx) {
        urlEx.printStackTrace();
        throw new Error("URL creation failed.");
    }
    try {
        BufferedReader reader = new BufferedReader(new InputStreamReader(urlObj.openStream()));
