            if (gg++ >= 500) break;
            Question tq = (Question) iter.next();
            sb.append("a=");
            sb.append(URLEncoder.encode(tq.question, "UTF-8"));
            sb.append("*");
            StringBuffer ss = new StringBuffer();
            String[] ans;
            if (tq.ansDisplay != null) {
                ans = tq.ansDisplay;
            } else {
                ans = tq.answer;
            }
            for (int j = 0; j < ans.length; j++) {
                if (j > 0) ss.append("*");
                ss.append(ans[j]);
            }
            sb.append(URLEncoder.encode(ss.toString(), "UTF-8"));
            if (iter.hasNext() && gg < 500) sb.append("&");
        }
        out.println(sb.toString());
        out.close();
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        String inputLine;
        if ((inputLine = in.readLine()) != null) {
            if (!inputLine.equals("OK!") && inputLine.length() > 3) {
                System.out.println("Not OK: " + inputLine);
                return "xxxxxxxxxx";
            }
        }
        in.close();
        return id;
    } catch (Exception e) {
        e.printStackTrace();
    }
    return null;
}

private final void copyTargetFileToSourceFile(File sourceFile, File targetFile) throws MJProcessorException {
