    fos.close();
}

private void downloadPage(final URL url, final File file) {
    try {
        long size = 0;
        final byte[] buffer = new byte[BotUtil.BUFFER_SIZE];
        final File tempFile = new File(file.getParentFile(), "temp.tmp");
        int length;
        int lastUpdate = 0;
        FileOutputStream fos = new FileOutputStream(tempFile);
        final InputStream is = url.openStream();
        do {
            length = is.read(buffer);
            if (length >= 0) {
                fos.write(buffer, 0, length);
                size += length;
            }
            if (lastUpdate > UPDATE_TIME) {
                report(0, (int) (size / Format.MEMORY_MEG), "Downloading... " + Format.formatMemory(size));
                lastUpdate = 0;
            }
            lastUpdate++;
        } while (length >= 0);
        fos.close();
        if (url.toString().toLowerCase().endsWith(".gz")) {
            final FileInputStream fis = new FileInputStream(tempFile);
            final GZIPInputStream gis = new GZIPInputStream(fis);
            fos = new FileOutputStream(file);
            size = 0;
            lastUpdate = 0;
            do {
                length = gis.read(buffer);
                if (length >= 0) {
                    fos.write(buffer, 0, length);
                    size += length;
                }
                if (lastUpdate > UPDATE_TIME) {
                    report(0, (int) (size / Format.MEMORY_MEG), "Uncompressing... " + Format.formatMemory(size));
                    lastUpdate = 0;
                }
                lastUpdate++;
            } while (length >= 0);
            fos.close();
            fis.close();
            gis.close();
            tempFile.delete();
        } else {
            file.delete();
            tempFile.renameTo(file);
        }
    } catch (final IOException e) {
        throw new AnalystError(e);
    }
}

public static boolean filecopy(final File source, final File target) {
    boolean out = false;
    if (source.isDirectory() || !source.exists() || target.isDirectory() || source.equals(target)) return false;
    try {
        target.getParentFile().mkdirs();
        target.createNewFile();
        FileChannel sourceChannel = new FileInputStream(source).getChannel();
        try {
            FileChannel targetChannel = new FileOutputStream(target).getChannel();
            try {
                targetChannel.transferFrom(sourceChannel, 0, sourceChannel.size());
                out = true;
            } finally {
                targetChannel.close();
            }
        } finally {
            sourceChannel.close();
        }
    } catch (IOException e) {
        out = false;
    }
    return out;
}

