    String twoHyphens = "--";
    String boundary = "******";
    try {
        URL url = new URL(uploadUrl);
        HttpURLConnection httpURLConnection = (HttpURLConnection) url.openConnection();
        httpURLConnection.setDoInput(true);
        httpURLConnection.setDoOutput(true);
        httpURLConnection.setUseCaches(false);
        httpURLConnection.setRequestMethod("POST");
        httpURLConnection.setRequestProperty("Connection", "Keep-Alive");
        httpURLConnection.setRequestProperty("Charset", "UTF-8");
        httpURLConnection.setRequestProperty("Content-Type", "multipart/form-data;boundary=" + boundary);
        DataOutputStream dos = new DataOutputStream(httpURLConnection.getOutputStream());
        dos.writeBytes(twoHyphens + boundary + end);
        dos.writeBytes("Content-Disposition: form-data; name=\"file\"; filename=\"" + srcPath.substring(srcPath.lastIndexOf("/") + 1) + "\"" + end);
        dos.writeBytes(end);
        FileInputStream fis = new FileInputStream(srcPath);
        byte[] buffer = new byte[8192];
        int count = 0;
        while ((count = fis.read(buffer)) != -1) {
            dos.write(buffer, 0, count);
        }
        fis.close();
        dos.writeBytes(end);
        dos.writeBytes(twoHyphens + boundary + twoHyphens + end);
        dos.flush();
        InputStream is = httpURLConnection.getInputStream();
        InputStreamReader isr = new InputStreamReader(is, "utf-8");
        BufferedReader br = new BufferedReader(isr);
        jsonstring = br.readLine();
        dos.close();
        is.close();
        return jsonstring;
    } catch (Exception e) {
        e.printStackTrace();
    }
    return jsonstring;
}

private String md5(String... args) throws FlickrException {
    try {
        StringBuilder sb = new StringBuilder();
        for (String str : args) {
            sb.append(str);
        }
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(sb.toString().getBytes());
        byte[] bytes = md.digest();
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            String hx = Integer.toHexString(0xFF & b);
            if (hx.length() == 1) {
                hx = "0" + hx;
            }
            result.append(hx);
        }
        return result.toString();
    } catch (Exception ex) {
        throw new FlickrException(ex);
    }
}

