protected String getPostRequestContent(String urlText, String... postParams) throws Exception {
    URL url = new URL(urlText);
    HttpURLConnection urlcon = (HttpURLConnection) url.openConnection();
    urlcon.setRequestMethod("POST");
    urlcon.setUseCaches(false);
    urlcon.setDoOutput(true);
    PrintStream ps = new PrintStream(urlcon.getOutputStream());
    for (String param : postParams) {
        ps.print(param);
    }
    ps.close();
    urlcon.connect();
    BufferedReader reader = new BufferedReader(new InputStreamReader(urlcon.getInputStream()));
    String line = reader.readLine();
    reader.close();
    urlcon.disconnect();
    return line;
}

private URL resolveRedirects(URL url, int redirectCount) throws IOException {
    URLConnection uc = url.openConnection();
    if (uc instanceof HttpURLConnection) {
        HttpURLConnection huc = (HttpURLConnection) uc;
        huc.setInstanceFollowRedirects(false);
        huc.connect();
        int responseCode = huc.getResponseCode();
        String location = huc.getHeaderField("location");
        huc.disconnect();
        if ((responseCode == HttpURLConnection.HTTP_MOVED_TEMP) && (redirectCount < 5)) {
            try {
                URL newUrl = new URL(location);
                return resolveRedirects(newUrl, redirectCount + 1);
            } catch (MalformedURLException ex) {
                return url;
            }
        } else return url;
    } else return url;
}

public static String loadPage(URL url) throws IOException {
    Reader in = null;
    URLConnection uc;
    HttpURLConnection huc = null;
    try {
        uc = url.openConnection();
        if (uc instanceof HttpURLConnection) {
            huc = (HttpURLConnection) uc;
            huc.setInstanceFollowRedirects(false);
            huc.connect();
            in = new InputStreamReader(huc.getInputStream());
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = in.read()) != -1) sb.append((char) c);
            return sb.toString();
        } else return null;
    } finally {
        try {
            if (in != null) in.close();
            if (huc != null) huc.disconnect();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }
}

