        ftp.setRemoteHost(host);
        ftp.setMessageListener(listener);
    } catch (final UnknownHostException e) {
        showConnectError();
        return;
    } catch (final Exception e) {
        e.printStackTrace();
    }
    final TileInfoManager tileInfoMgr = TileInfoManager.getInstance();
