private void download(String address, String localFileName) throws UrlNotFoundException, Exception {
    String ext = G_File.getExtensao(address);
    if (ext.equals("jsp")) {
        throw new Exception("Erro ao baixar pagina JSP, tipo negado." + address);
    }
    File temp = new File(localFileName + ".tmp");
    if (temp.exists()) temp.delete();
    OutputStream out = null;
    URLConnection conn = null;
    InputStream in = null;
    try {
        try {
            URL url = new URL(address);
            conn = url.openConnection();
            in = conn.getInputStream();
        } catch (FileNotFoundException e2) {
            throw new UrlNotFoundException();
        }
        out = new BufferedOutputStream(new FileOutputStream(temp));
        byte[] buffer = new byte[1024];
        int numRead;
        long numWritten = 0;
        while ((numRead = in.read(buffer)) != -1) {
            out.write(buffer, 0, numRead);
            numWritten += numRead;
        }
    } catch (UrlNotFoundException exception) {
        throw exception;
    } catch (Exception exception) {
        throw exception;
    } finally {
        try {
            if (in != null) {
                in.close();
            }
            if (out != null) {
                out.close();
            }
        } catch (IOException ioe) {
        }
    }
    File oldArq = new File(localFileName);
    if (oldArq.exists()) {
        oldArq.delete();
    }
    oldArq = null;
    File nomeFinal = new File(localFileName);
    temp.renameTo(nomeFinal);
}

private int[] sort(int n) {
    int[] mas = new int[n];
    Random rand = new Random();
    for (int i = 0; i < n; i++) {
        mas[i] = rand.nextInt(10) + 1;
    }
    boolean t = true;
    int tmp = 0;
    while (t) {
        t = false;
        for (int i = 0; i < mas.length - 1; i++) {
            if (mas[i] > mas[i + 1]) {
                tmp = mas[i];
                mas[i] = mas[i + 1];
                mas[i + 1] = tmp;
                t = true;
            }
        }
    }
    return mas;
}

