private void bubbleSort() {
    for (int i = 0; i < testfield.length; i++) {
        for (int j = 0; j < testfield.length - i - 1; j++) if (testfield[j] > testfield[j + 1]) {
            short temp = testfield[j];
            testfield[j] = testfield[j + 1];
            testfield[j + 1] = temp;
        }
    }
}

