public SimpleParser(String filepath) throws Exception {
    this.path = filepath;
    InputStream is = null;
    try {
        if (this.path.indexOf("http") == 0) {
            URL url = new URL(this.path);
            is = url.openStream();
        } else if (this.path.indexOf("<?xml") == 0) {
            is = new ByteArrayInputStream(filepath.getBytes(encoding));
        } else {
            File f = new File(this.path);
            if (!f.exists()) {
                setError("File not found : " + this.path);
            } else {
                is = new FileInputStream(f);
            }
        }
        if (is != null) {
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            doc = dBuilder.parse(is);
            doc.getDocumentElement().normalize();
        }
    } catch (Exception ex) {
        Malgn.errorLog("{SimpleParser.constructor} Path:" + filepath + " " + ex.getMessage());
        setError("Parser Error : " + ex.getMessage());
    } finally {
        if (is != null) is.close();
    }
}

private Element makeRequest(String link) {
    try {
        URL url = new URL(link);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.connect();
        InputStream in = conn.getInputStream();
        DocumentBuilder builder = DocumentBuilderFactory.newInstance().newDocumentBuilder();
        Document document = builder.parse(in);
        Element element = document.getDocumentElement();
        element.normalize();
        if (checkRootTag(element)) {
            return element;
        } else {
            return null;
        }
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    } catch (ParserConfigurationException e) {
        e.printStackTrace();
        return null;
    } catch (SAXException e) {
        e.printStackTrace();
        return null;
    }
}

