                line = rdr.readLine();
            }
            return result;
        } catch (IOException ex) {
            if (retries == 5) {
                logger.debug("Problem getting url content exhausted");
                return result;
            } else {
                logger.debug("Problem getting url content retrying..." + urlString);
                try {
                    Thread.sleep((int) Math.pow(2.0, retries) * 1000);
                } catch (InterruptedException e) {
                }
                retries++;
            }
        }
    }
}

public void start(OutputStream bytes, Target target) throws IOException {
    URLConnection conn = url.openConnection();
    InputStream fis = conn.getInputStream();
    byte[] buf = new byte[4096];
    while (true) {
        int bytesRead = fis.read(buf);
        if (bytesRead < 1) break;
        bytes.write(buf, 0, bytesRead);
    }
    fis.close();
}

