        FileOutputStream out = new FileOutputStream(file);
        byte buf[] = new byte[1024];
        int len;
        while ((len = inputStream.read(buf)) > 0) out.write(buf, 0, len);
        out.close();
        inputStream.close();
        byte[] buffer = new byte[Math.max((int) (file.length() * 1.4), 40)];
        int length = 0;
