public synchronized void downloadTile(TileNumber tn) {
    try {
        Bitmap tile = getMapFromSdCache(tn);
        if (tile == null) {
            URL url = new URL("http://tile.openstreetmap.org/" + tn.getZoom() + "/" + tn.getX() + "/" + tn.getY() + ".png");
