public static boolean copyFile(String sourceFileName, String destFileName) {
    if (sourceFileName == null || destFileName == null) return false;
    if (sourceFileName.equals(destFileName)) return false;
    try {
        java.io.FileInputStream in = new java.io.FileInputStream(sourceFileName);
        java.io.FileOutputStream out = new java.io.FileOutputStream(destFileName);
        try {
            byte[] buf = new byte[31000];
            int read = in.read(buf);
            while (read > -1) {
                out.write(buf, 0, read);
                read = in.read(buf);
            }
        } finally {
            in.close();
            out.close();
        }
    } catch (Exception e) {
        System.out.println(e.toString());
        return false;
    }
    return true;
}

public static boolean copyFile(final String src, final String dest) {
    if (fileExists(src)) {
        try {
            FileChannel srcChannel = new FileInputStream(src).getChannel();
            FileChannel dstChannel = new FileOutputStream(dest).getChannel();
            dstChannel.transferFrom(srcChannel, 0, srcChannel.size());
            srcChannel.close();
            dstChannel.close();
            return true;
        } catch (IOException e) {
            Logger.getAnonymousLogger().severe(e.getLocalizedMessage());
        }
    }
    return false;
}

public String encrypt(String plaintext) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("SHA");
    } catch (NoSuchAlgorithmException e) {
        System.err.println(e.getMessage());
    }
    try {
        md.update(plaintext.getBytes("UTF-8"));
    } catch (UnsupportedEncodingException e) {
        System.err.println(e.getMessage());
    }
    byte raw[] = md.digest();
    String hash = (new BASE64Encoder()).encode(raw);
    return hash;
}

