private static InputSource getInputSourceFromURI(String uri, String username, String password) throws IOException, ProtocolException, UnsupportedEncodingException {
    URL wsdlurl = null;
    try {
        wsdlurl = new URL(uri);
    } catch (MalformedURLException e) {
        return new InputSource(uri);
    }
    if (username == null && wsdlurl.getUserInfo() == null) {
        return new InputSource(uri);
    }
    if (!wsdlurl.getProtocol().startsWith("http")) {
        return new InputSource(uri);
    }
    URLConnection connection = wsdlurl.openConnection();
    if (!(connection instanceof HttpURLConnection)) {
        return new InputSource(uri);
    }
    HttpURLConnection uconn = (HttpURLConnection) connection;
    String userinfo = wsdlurl.getUserInfo();
    uconn.setRequestMethod("GET");
    uconn.setAllowUserInteraction(false);
    uconn.setDefaultUseCaches(false);
    uconn.setDoInput(true);
    uconn.setDoOutput(false);
    uconn.setInstanceFollowRedirects(true);
    uconn.setUseCaches(false);
    String auth = null;
    if (userinfo != null) {
        auth = userinfo;
    } else if (username != null) {
        auth = (password == null) ? username : username + ":" + password;
    }
    if (auth != null) {
        uconn.setRequestProperty("Authorization", "Basic " + base64encode(auth.getBytes(charEncoding)));
    }
    uconn.connect();
    return new InputSource(uconn.getInputStream());
}

@Override
public HttpResponse makeRequest() throws RequestCancelledException, IllegalStateException, IOException {
    checkState();
    OutputStream out = null;
    InputStream in = null;
    try {
        out = new BufferedOutputStream(new FileOutputStream(destFile));
        URLConnection conn = url.openConnection();
        in = conn.getInputStream();
        byte[] buffer = new byte[BUFFRE_SIZE];
        int numRead;
        long totalSize = conn.getContentLength();
        long transferred = 0;
        started(totalSize);
        while (!checkAbortFlag() && (numRead = in.read(buffer)) != -1) {
            out.write(buffer, 0, numRead);
            out.flush();
            transferred += numRead;
            progress(transferred);
        }
        if (checkAbortFlag()) {
            cancelled();
        } else {
            finished();
        }
        if (checkAbortFlag()) {
            throw new RequestCancelledException();
        }
    } finally {
        if (out != null) {
            out.close();
        }
        if (in != null) {
            in.close();
        }
    }
    return null;
}

