private static String[] loadDB(String name) throws IOException {
    URL url = SpecialConstants.class.getResource(name);
    if (url == null) throw new FileNotFoundException("file " + name + " not found");
    InputStream is = url.openStream();
    try {
        InputStreamReader isr = new InputStreamReader(is, "utf8");
        BufferedReader br = new BufferedReader(isr);
        ArrayList<String> entries = new ArrayList<String>();
        while (true) {
            String line = br.readLine();
            if (line == null) break;
            line = line.trim();
            if (line.length() > 0 && line.charAt(0) != '#') {
                entries.add(line);
            }
        }
        String[] r = new String[entries.size()];
        entries.toArray(r);
        return r;
    } finally {
        is.close();
    }
}

public static void copyFile(String sourceName, String destName) throws IOException {
    FileChannel sourceChannel = null;
    FileChannel destChannel = null;
    try {
        sourceChannel = new FileInputStream(sourceName).getChannel();
        destChannel = new FileOutputStream(destName).getChannel();
        destChannel.transferFrom(sourceChannel, 0, sourceChannel.size());
    } catch (IOException exception) {
        throw exception;
    } finally {
        if (sourceChannel != null) {
            try {
                sourceChannel.close();
            } catch (IOException ex) {
            }
        }
        if (destChannel != null) {
            try {
                destChannel.close();
            } catch (IOException ex) {
            }
        }
    }
}

