public boolean PrintPage(String page, String url_addr, String charset) {
    File parent_path = new File(new File(page).getParent());
    if (!parent_path.exists()) {
        parent_path.mkdirs();
    }
    String r_line = null;
    BufferedReader bReader = null;
    FileOutputStream out = null;
    OutputStreamWriter writer = null;
    PrintWriter fileOut = null;
    File file = null;
    try {
        InputStream ins = new URL(url_addr).openStream();
        file = new File(page);
        if (!file.exists()) {
            file.createNewFile();
        }
        bReader = new BufferedReader(new InputStreamReader(ins, charset));
        out = new FileOutputStream(page);
        writer = new OutputStreamWriter(out, charset);
        fileOut = new PrintWriter(writer);
        while ((r_line = bReader.readLine()) != null) {
            r_line = r_line.trim();
            int str_len = r_line.length();
            if (str_len > 0) {
                fileOut.println(r_line);
                fileOut.flush();
            }
        }
        ins.close();
        ins = null;
        fileOut.close();
        writer.close();
        out.close();
        bReader.close();
        fileOut = null;
        writer = null;
        out = null;
        bReader = null;
        parent_path = null;
        file = null;
        r_line = null;
        return true;
    } catch (IOException ioe) {
        log.error(ioe.getMessage());
        ioe.printStackTrace();
        return false;
    } catch (Exception es) {
        es.printStackTrace();
        log.error("static----------" + es.getMessage());
        return false;
    } finally {
        try {
            if (fileOut != null) {
                fileOut.close();
                fileOut = null;
            }
            if (writer != null) {
                writer.close();
                writer = null;
            }
            if (out != null) {
                out.close();
                out = null;
            }
            if (bReader != null) {
                bReader.close();
                bReader = null;
            }
        } catch (IOException ioe) {
            log.error(ioe.getMessage());
        } catch (Exception e) {
            log.error(e.getMessage());
        }
    }
}

public String hash(String plaintext, String salt, int iterations) throws EncryptionException {
    byte[] bytes = null;
    try {
        MessageDigest digest = MessageDigest.getInstance(hashAlgorithm);
        digest.reset();
        digest.update(ESAPI.securityConfiguration().getMasterSalt());
        digest.update(salt.getBytes(encoding));
        digest.update(plaintext.getBytes(encoding));
        bytes = digest.digest();
        for (int i = 0; i < iterations; i++) {
            digest.reset();
            bytes = digest.digest(bytes);
        }
        String encoded = ESAPI.encoder().encodeForBase64(bytes, false);
        return encoded;
    } catch (NoSuchAlgorithmException e) {
        throw new EncryptionException("Internal error", "Can't find hash algorithm " + hashAlgorithm, e);
    } catch (UnsupportedEncodingException ex) {
        throw new EncryptionException("Internal error", "Can't find encoding for " + encoding, ex);
    }
}

public void SendFile(File testfile) {
    try {
        SocketChannel sock = SocketChannel.open(new InetSocketAddress("127.0.0.1", 1234));
        sock.configureBlocking(true);
        while (!sock.finishConnect()) {
            System.out.println("NOT connected!");
        }
        System.out.println("CONNECTED!");
        FileInputStream fis = new FileInputStream(testfile);
        FileChannel fic = fis.getChannel();
        long len = fic.size();
        Buffer.clear();
        Buffer.putLong(len);
        Buffer.flip();
        sock.write(Buffer);
        long cnt = 0;
        while (cnt < len) {
            Buffer.clear();
            int add = fic.read(Buffer);
            cnt += add;
            Buffer.flip();
            while (Buffer.hasRemaining()) {
                sock.write(Buffer);
            }
        }
        fic.close();
        File tmpfile = getTmp().createNewFile("tmp", "tmp");
        FileOutputStream fos = new FileOutputStream(tmpfile);
        FileChannel foc = fos.getChannel();
        int mlen = -1;
        do {
            Buffer.clear();
            mlen = sock.read(Buffer);
            Buffer.flip();
            if (mlen > 0) {
                foc.write(Buffer);
            }
        } while (mlen > 0);
        foc.close();
    } catch (IOException e) {
        e.printStackTrace();
    }
}

