        m_day = 0;
    }
    while (m_isRunning) {
        m_minutes = m_minutes == 59 ? 0 : m_minutes + 1;
        if (m_minutes == 0) {
            if (m_hour == 23) {
                incrementDay();
                m_hour = 0;
            } else {
                m_hour += 1;
            }
        }
        m_hour = m_hour == 23 ? 0 : m_hour + 1;
