            md.update(":".getBytes());
            md.update(nonce.getBytes());
            md.update(":".getBytes());
            md.update(cnonce.getBytes());
            d = md.digest();
        }
        byte[] a1 = bytesToHex(d);
        md = MessageDigest.getInstance("MD5");
        md.update(method.getBytes());
        md.update(":".getBytes());
        md.update(uri.getBytes());
        d = md.digest();
        byte[] a2 = bytesToHex(d);
        md = MessageDigest.getInstance("MD5");
        md.update(a1);
        md.update(":".getBytes());
        md.update(nonce.getBytes());
        md.update(":".getBytes());
        if (null != qop) {
            md.update(nonceCount.getBytes());
            md.update(":".getBytes());
            md.update(cnonce.getBytes());
            md.update(":".getBytes());
            md.update(qop.getBytes());
            md.update(":".getBytes());
        }
        md.update(a2);
        d = md.digest();
        byte[] r = bytesToHex(d);
        digest = new String(r);
    } catch (Exception e) {
        e.printStackTrace();
    }
    return digest;
}

private static boolean CopyFile(File srcFile, File tagFile) throws IOException {
    if (srcFile == null || tagFile == null) {
        return false;
    }
    int length = 2097152;
    File dirFile = new File(getFileFolder(tagFile.getAbsolutePath()));
    if (!dirFile.exists()) {
        dirFile.mkdirs();
    }
    FileInputStream in = new FileInputStream(srcFile);
    FileOutputStream out = new FileOutputStream(tagFile.getAbsolutePath());
    FileChannel inC = in.getChannel();
    FileChannel outC = out.getChannel();
    int i = 0;
    while (true) {
        if (inC.position() == inC.size()) {
            inC.close();
            outC.close();
            break;
        }
        if ((inC.size() - inC.position()) < 20971520) length = (int) (inC.size() - inC.position()); else length = 20971520;
        inC.transferTo(inC.position(), length, outC);
        inC.position(inC.position() + length);
        i++;
    }
    return true;
}

