public static String buildUserPassword(String password) {
    String result = "";
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("MD5");
        md.update(password.getBytes("UTF8"));
        byte[] hash = md.digest();
        for (int i = 0; i < hash.length; i++) {
            int hexValue = hash[i] & 0xFF;
            if (hexValue < 16) {
                result = result + "0";
            }
            result = result + Integer.toString(hexValue, 16);
        }
        logger.debug("Users'password MD5 Digest: " + result);
    } catch (NoSuchAlgorithmException ex) {
        logger.error(ex.getMessage());
        ex.printStackTrace();
    } catch (UnsupportedEncodingException ex) {
        logger.error(ex.getMessage());
        ex.printStackTrace();
    }
    return result;
}

public static String plainToMD(LoggerCollection loggerCol, String input) {
    byte[] byteHash = null;
    MessageDigest md = null;
    StringBuilder md5result = new StringBuilder();
    try {
        md = MessageDigest.getInstance("MD5");
        md.reset();
        md.update(input.getBytes());
        byteHash = md.digest();
        for (int i = 0; i < byteHash.length; i++) {
            md5result.append(Integer.toHexString(0xFF & byteHash[i]));
        }
    } catch (NoSuchAlgorithmException ex) {
        loggerCol.logException(CLASSDEBUG, "de.searchworkorange.lib.misc.hash.MD5Hash", Level.FATAL, ex);
    }
    return (md5result.toString());
}

