            FileChannel source = new FileInputStream(sourceFile).getChannel();
            FileChannel destination = new FileOutputStream(destinationFile).getChannel();
            destination.transferFrom(source, 0, source.size());
            source.close();
            destination.close();
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}

