}

public static String loadUrlContentAsString(URL url) throws IOException {
    char[] buf = new char[2048];
    StringBuffer ret = new StringBuffer();
    BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
    for (int chars = reader.read(buf); chars != -1; chars = reader.read(buf)) {
        ret.append(buf, 0, chars);
    }
    reader.close();
    return ret.toString();
}

public static boolean copyFile(File from, File to) {
    try {
        FileChannel fromChannel = new FileInputStream(from).getChannel();
        FileChannel toChannel = new FileOutputStream(to).getChannel();
        toChannel.transferFrom(fromChannel, 0, fromChannel.size());
        fromChannel.close();
        toChannel.close();
    } catch (IOException e) {
        log.error("failed to copy " + from.getAbsolutePath() + " to " + to.getAbsolutePath() + ": caught exception", e);
        return false;
    }
    return true;
}

