public void run() {
    long id = 0;
    try {
        URL url = new URL(httpRequest + blockSize);
        BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));
        try {
            String str = in.readLine();
            if (str == null) {
                throw new IllegalStateException("Parsing error");
            }
            if (str.matches(".*SUCCESS.*")) {
                str = in.readLine();
                if (str.matches(".*Start:.*")) {
                    str = in.readLine();
                    id = Long.parseLong(str);
                } else {
                    throw new IllegalStateException("Invalid response for blocksize(" + blockSize + "):" + str);
                }
            } else {
                throw new IllegalStateException("Invalid response for blocksize(" + blockSize + "):" + str);
            }
        } finally {
            in.close();
        }
        if (id <= 0) throw new IllegalStateException("Invalid GUID start value " + id);
        synchronized (ids) {
            boolean absent = ids.add(new Long(id));
            if (!absent) {
                logErrorMessage(id + " already exists for thread " + Thread.currentThread().getName());
            }
        }
    } catch (Exception e) {
        logErrorMessage("Unexpected IdGenerator thread failure" + e.getMessage());
        e.printStackTrace();
    } finally {
        synchronized (test) {
            test.liveThreads--;
            test.notify();
        }
    }
}

private static String getSignature(String data) {
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
        return "FFFFFFFFFFFFFFFF";
    }
    md.update(data.getBytes());
    StringBuffer sb = new StringBuffer();
    byte[] sign = md.digest();
    for (int i = 0; i < sign.length; i++) {
        byte b = sign[i];
        int in = (int) b;
        if (in < 0) in = 127 - b;
        String hex = Integer.toHexString(in).toUpperCase();
        if (hex.length() == 1) hex = "0" + hex;
        sb.append(hex);
    }
    return sb.toString();
}

public void render(HttpServletRequest request, HttpServletResponse response, File file, final Throwable t, final String contentType, final String encoding) throws Exception {
    if (contentType != null) {
        response.setContentType(contentType);
    }
    if (encoding != null) {
        response.setCharacterEncoding(encoding);
    }
    if (file.length() > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Cannot send file greater than 2GB");
    }
    response.setContentLength((int) file.length());
    IOUtils.copy(new FileInputStream(file), response.getOutputStream());
}

