        buffer.append(content.length());
        expected = new String(Hex.encodeHex(messageDigest.digest(buffer.toString().getBytes())));
        etag = new FileETag();
        etag.setFlags(FileETag.FLAG_CONTENT | FileETag.FLAG_MTIME | FileETag.FLAG_SIZE);
