public static String getMD5(String s) throws NoSuchAlgorithmException {
    MessageDigest md5 = MessageDigest.getInstance("MD5");
    md5.reset();
    md5.update(s.getBytes());
    byte[] result = md5.digest();
    StringBuilder hexString = new StringBuilder();
    for (int i = 0; i < result.length; i++) {
        hexString.append(String.format("%02x", 0xFF & result[i]));
    }
    return hexString.toString();
}

public String requestGET(String baseUrl, Map<String, String> params) throws Exception {
    String result = "";
    StringBuffer url = new StringBuffer();
    url.append(baseUrl);
    if (params != null && !params.isEmpty()) {
        List<String> keys = new ArrayList<String>(params.keySet());
        for (String key : keys) {
            url.append(key);
            url.append("/");
            url.append(URLEncoder.encode(params.get(key), "UTF-8"));
        }
    }
    HttpGet get = new HttpGet(url.toString());
    HttpResponse res = client.execute(get);
    HttpEntity entity = null;
    if (res.getStatusLine().getStatusCode() == HttpStatus.SC_OK) {
        entity = res.getEntity();
        BufferedReader in = new BufferedReader(new InputStreamReader(entity.getContent()));
        String read = "";
        StringBuffer content = new StringBuffer();
        while ((read = in.readLine()) != null) {
            content.append(read);
        }
        in.close();
        JSONObject rObj = new JSONObject(content.toString());
        result = rObj.getString("msg");
    } else {
        result = "HTTP请求失败";
    }
    if (entity != null) entity.consumeContent();
    client.getConnectionManager().shutdown();
    get = null;
    return result;
}

public String requestPOST(String baseUrl, Map<String, String> params) throws Exception {
    String result = "";
    HttpPost request = new HttpPost(baseUrl);
    HttpEntity entity = null;
    if (params != null && !params.isEmpty()) {
        List<NameValuePair> postParams = new ArrayList<NameValuePair>();
        List<String> keys = new ArrayList<String>(params.keySet());
        for (String key : keys) {
            postParams.add(new BasicNameValuePair(key, params.get(key)));
        }
        entity = new UrlEncodedFormEntity(postParams, "utf-8");
        request.setEntity(entity);
    }
    HttpResponse res = client.execute(request);
    if (res.getStatusLine().getStatusCode() == HttpStatus.SC_OK) {
        entity = res.getEntity();
        BufferedReader in = new BufferedReader(new InputStreamReader(entity.getContent()));
        StringBuffer content = new StringBuffer();
        String read = "";
        while ((read = in.readLine()) != null) {
            content.append(read);
        }
        in.close();
        JSONObject rObj = new JSONObject(content.toString());
        result = rObj.getString("msg");
    } else result = "请求失败了";
    entity.consumeContent();
    client.getConnectionManager().shutdown();
    request = null;
    return result;
}

