            dos.flush();
            dos.close();
            huc.disconnect();
        } catch (MalformedURLException e) {
            logger.error(e);
            e.printStackTrace();
        } catch (IOException e) {
            logger.equals(e);
            e.printStackTrace();
        }
    }
}

