            int commentPos = line.indexOf('#');
            if (commentPos >= 0) {
                line = line.substring(0, commentPos);
            }
            line = line.trim();
            int len = line.length();
            if (len != 0) {
                if (result != null) {
                    print(err, "checkconfig.multiproviders", url.toString());
