public static void copy(final File src, final File dst) throws IOException, IllegalArgumentException {
    long fileSize = src.length();
    final FileInputStream fis = new FileInputStream(src);
    final FileOutputStream fos = new FileOutputStream(dst);
    final FileChannel in = fis.getChannel(), out = fos.getChannel();
    try {
        long offs = 0, doneCnt = 0;
        final long copyCnt = Math.min(65536, fileSize);
        do {
            doneCnt = in.transferTo(offs, copyCnt, out);
            offs += doneCnt;
            fileSize -= doneCnt;
        } while (fileSize > 0);
    } finally {
        try {
            in.close();
        } catch (final IOException e) {
        }
        try {
            out.close();
        } catch (final IOException e) {
        }
        try {
            fis.close();
        } catch (final IOException e) {
        }
        try {
            fos.close();
        } catch (final IOException e) {
        }
        src.delete();
    }
}

private static void compressZip(String source, String dest) throws Exception {
    File baseFolder = new File(source);
    if (baseFolder.exists()) {
        if (baseFolder.isDirectory()) {
            List<File> fileList = getSubFiles(new File(source));
            ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(dest));
            zos.setEncoding("GBK");
            ZipEntry entry = null;
            byte[] buf = new byte[2048];
            int readLen = 0;
            for (int i = 0; i < fileList.size(); i++) {
                File file = fileList.get(i);
                if (file.isDirectory()) {
                    entry = new ZipEntry(getAbsFileName(source, file) + "/");
                } else {
                    entry = new ZipEntry(getAbsFileName(source, file));
                }
                entry.setSize(file.length());
                entry.setTime(file.lastModified());
                zos.putNextEntry(entry);
                if (file.isFile()) {
                    InputStream in = new BufferedInputStream(new FileInputStream(file));
                    while ((readLen = in.read(buf, 0, 1024)) != -1) {
                        zos.write(buf, 0, readLen);
                    }
                    in.close();
                }
            }
            zos.close();
        } else {
            throw new Exception("Can not do this operation!.");
        }
    } else {
        baseFolder.mkdirs();
        compressZip(source, dest);
    }
}

