private static void copyFile(String src, String dest) throws IOException {
    File destFile = new File(dest);
    if (destFile.exists()) {
        destFile.delete();
    }
    FileChannel srcChannel = new FileInputStream(src).getChannel();
    FileChannel dstChannel = new FileOutputStream(dest).getChannel();
    dstChannel.transferFrom(srcChannel, 0, srcChannel.size());
    srcChannel.close();
    dstChannel.close();
}

public static String encryption(String oldPass) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException ex) {
        ex.printStackTrace();
    }
    md.update(oldPass.getBytes());
    byte b[] = md.digest();
    int i;
    StringBuffer buf = new StringBuffer();
    for (int offset = 0; offset < b.length; offset++) {
        i = b[offset];
        if (i < 0) {
            i += 256;
        }
        if (i < 16) {
            buf.append("0");
        }
        buf.append(Integer.toHexString(i));
    }
    String pass32 = buf.toString();
    return pass32;
}

private void copy(File source, File destination) {
    if (!destination.exists()) {
        destination.mkdir();
    }
    File files[] = source.listFiles();
    if (files != null) {
        for (int i = 0; i < files.length; i++) {
            if (files[i].isDirectory()) {
                copy(files[i], new File(destination, files[i].getName()));
            } else {
                try {
                    FileChannel srcChannel = new FileInputStream(files[i]).getChannel();
                    FileChannel dstChannel = new FileOutputStream(new File(destination, files[i].getName())).getChannel();
                    dstChannel.transferFrom(srcChannel, 0, srcChannel.size());
                    srcChannel.close();
                    dstChannel.close();
                } catch (IOException ioe) {
                    log.error("Could not write to " + destination.getAbsolutePath(), ioe);
                }
            }
        }
    }
}

