        }
        archiveOutput.close();
        responseInput.close();
    } catch (IOException exception) {
        monitor.setCanceled(true);
        throw new InvocationTargetException(exception);
    }
    monitor.beginTask("Downloading FFMpeg, extracting executable", 1);
