        while ((zipEntry = zipStream.getNextEntry()) != null) {
            if (zipEntry.getName().equals(fileToExtract)) {
                int size = (int) zipEntry.getSize();
                for (int i = 0; i < size; i++) {
                    writer.write(zipStream.read());
                }
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    } finally {
        if (zipStream != null) try {
            zipStream.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (writer != null) try {
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

