private String getMd5(String base64image) {
    String token = null;
    try {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        md5.update(base64image.getBytes());
        BigInteger hash = new BigInteger(1, md5.digest());
        token = hash.toString(16);
    } catch (NoSuchAlgorithmException nsae) {
    }
    return token;
}

private String hash(String message) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("SHA1");
    } catch (NoSuchAlgorithmException e) {
        throw new AssertionError("Can't find the SHA1 algorithm in the java.security package");
    }
    String saltString = String.valueOf(12345);
    md.update(saltString.getBytes());
    md.update(message.getBytes());
    byte[] digestBytes = md.digest();
    StringBuffer digestSB = new StringBuffer();
    for (int i = 0; i < digestBytes.length; i++) {
        int lowNibble = digestBytes[i] & 0x0f;
        int highNibble = (digestBytes[i] >> 4) & 0x0f;
        digestSB.append(Integer.toHexString(highNibble));
        digestSB.append(Integer.toHexString(lowNibble));
    }
    String digestStr = digestSB.toString().trim();
    return digestStr;
}

protected int doExecuteUpdate(PreparedStatement statement) throws SQLException {
    connection.setAutoCommit(isAutoCommit());
    int rs = -1;
    try {
        lastError = null;
        rs = statement.executeUpdate();
        if (!isAutoCommit()) connection.commit();
    } catch (Exception ex) {
        if (!isAutoCommit()) {
            lastError = ex;
            connection.rollback();
            LogUtils.log(Level.SEVERE, "Transaction is being rollback. Error: " + ex.toString());
        }
    } finally {
        if (statement != null) statement.close();
    }
    return rs;
}

protected int doExecuteInsert(PreparedStatement statement, Table data) throws SQLException {
    ResultSet rs = null;
    int result = -1;
    try {
        lastError = null;
        result = statement.executeUpdate();
        if (!isAutoCommit()) connection.commit();
        rs = statement.getGeneratedKeys();
        while (rs.next()) {
            FieldUtils.setValue(data, data.key, rs.getObject(1));
        }
    } catch (SQLException ex) {
        if (!isAutoCommit()) {
            lastError = ex;
            connection.rollback();
            LogUtils.log(Level.SEVERE, "Transaction is being rollback. Error: " + ex.toString());
        } else {
            throw ex;
        }
    } finally {
        if (statement != null) statement.close();
        if (rs != null) rs.close();
    }
    return result;
}

