        int readBytes = 0;
        do {
            readBytes = fis.read(buffer);
            if (readBytes > 0) fos.write(buffer, 0, readBytes);
        } while (readBytes > 0);
        fos.close();
        fis.close();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

