        from = new FileInputStream(from_file);
        to = new FileOutputStream(to_file);
        byte[] buffer = new byte[4096];
        int bytes_read;
        while ((bytes_read = from.read(buffer)) != -1) {
            to.write(buffer, 0, bytes_read);
        }
    } finally {
        if (from != null) {
            try {
