protected static String readAFewChars(URL url) throws IOException {
    StringBuffer buf = new StringBuffer(10);
    Reader reader = new InputStreamReader(url.openStream());
    for (int i = 0; i < 10; i++) {
        int c = reader.read();
        if (c == -1) {
            break;
        }
        buf.append((char) c);
    }
    reader.close();
    return buf.toString();
}

public static void main(String[] args) {
    try {
        int encodeFlag = 0;
        if (args[0].equals("-e")) {
            encodeFlag = Base64.ENCODE;
        } else if (args[0].equals("-d")) {
            encodeFlag = Base64.DECODE;
        }
        String infile = args[1];
        String outfile = args[2];
        File fin = new File(infile);
        FileInputStream fis = new FileInputStream(fin);
        BufferedInputStream bis = new BufferedInputStream(fis);
        Base64.InputStream b64in = new Base64.InputStream(bis, encodeFlag | Base64.DO_BREAK_LINES);
        File fout = new File(outfile);
        FileOutputStream fos = new FileOutputStream(fout);
        BufferedOutputStream bos = new BufferedOutputStream(fos);
        byte[] buff = new byte[1024];
        int read = -1;
        while ((read = b64in.read(buff)) >= 0) {
            bos.write(buff, 0, read);
        }
        bos.close();
        b64in.close();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

