public static String contents(URL url) throws IOException {
    InputStream is = url.openStream();
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] buf = new byte[1024];
    while (true) {
        int len = is.read(buf);
        if (len < 0) {
            break;
        }
        baos.write(buf, 0, len);
    }
    is.close();
    String contents = new String(baos.toByteArray(), "iso8859_1");
    baos.close();
    return contents;
}

public static void copyFromFileToFileUsingNIO(File inputFile, File outputFile) throws FileNotFoundException, IOException {
    FileChannel inputChannel = new FileInputStream(inputFile).getChannel();
    FileChannel outputChannel = new FileOutputStream(outputFile).getChannel();
    try {
        inputChannel.transferTo(0, inputChannel.size(), outputChannel);
    } catch (IOException e) {
        throw e;
    } finally {
        if (inputChannel != null) inputChannel.close();
        if (outputChannel != null) outputChannel.close();
    }
}

