        throw problemaDetalhado;
    } finally {
        pAndamento.setPercentualCompleto(100);
        if (stmtLimpezaInicialDestino != null && (!stmtLimpezaInicialDestino.isClosed())) {
            stmtLimpezaInicialDestino.close();
        }
        if (stmtDestino != null && (!stmtDestino.isClosed())) {
            stmtDestino.close();
        }
    }
}

