        throw new BuildException("FTP connexion failed : " + ftp.getReplyString());
    }
    try {
        try {
            if (!ftp.login(userid, password)) {
                throw new BuildException("Identification failed");
            }
        } catch (IOException ex) {
            throw new BuildException(ex);
        }
        if (binary) {
