                is = value.getStream();
                IOUtils.copy(is, os);
                os.flush();
            } catch (Exception e) {
                throw new SAXException("Could not backup binary value of property [" + property.getName() + "]", e);
            } finally {
                if (null != is) {
                    try {
                        is.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
                if (null != os) {
                    try {
                        os.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }
            na.addAttribute("", ATTACHMENT, (NAMESPACE.length() > 0 ? NAMESPACE + ":" : "") + ATTACHMENT, "string", outResourceName);
            break;
        case PropertyType.REFERENCE:
            _value = value.getString();
            break;
        default:
            _value = value.getString();
    }
    contentHandler.startElement("", VALUE, (NAMESPACE.length() > 0 ? NAMESPACE + ":" : "") + VALUE, na);
    if (null != _value) contentHandler.characters(_value.toCharArray(), 0, _value.length());
    contentHandler.endElement("", VALUE, (NAMESPACE.length() > 0 ? NAMESPACE + ":" : "") + VALUE);
}

public InputStream getParameterAsInputStream(String key) throws UndefinedParameterError, IOException {
    String urlString = getParameter(key);
    if (urlString == null) return null;
    try {
        URL url = new URL(urlString);
        InputStream stream = url.openStream();
        return stream;
    } catch (MalformedURLException e) {
        File file = getParameterAsFile(key);
        if (file != null) {
            return new FileInputStream(file);
        } else {
            return null;
        }
    }
}

public final String hashPassword(final String password) {
    try {
        if (salt == null) {
            salt = new byte[16];
            SecureRandom sr = SecureRandom.getInstance("SHA1PRNG");
            sr.setSeed(System.currentTimeMillis());
            sr.nextBytes(salt);
        }
        MessageDigest md = MessageDigest.getInstance("SHA");
        md.update(salt);
        md.update(password.getBytes("UTF-8"));
        byte[] hash = md.digest();
        for (int i = 0; i < (1999); i++) {
            md.reset();
            hash = md.digest(hash);
        }
        return byteToString(hash, 60);
    } catch (Exception exception) {
        log.error(exception);
        return null;
    }
}

public final String hashPassword(String password) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA");
        md.update(password.getBytes());
        byte[] hash = md.digest();
        return "{SHA}" + byteToString(hash, 60);
    } catch (NoSuchAlgorithmException nsae) {
        log.error("Error getting password hash - " + nsae.getMessage());
        return null;
    }
}

public final String hashRealmPassword(String username, String realm, String password) throws GeneralSecurityException {
    MessageDigest md = null;
    md = MessageDigest.getInstance("MD5");
    md.update(username.getBytes());
    md.update(":".getBytes());
    md.update(realm.getBytes());
    md.update(":".getBytes());
    md.update(password.getBytes());
    byte[] hash = md.digest();
    return toHex(hash, hash.length);
}

