public String getPasswordMD5() {
    try {
        MessageDigest algorithm = MessageDigest.getInstance("MD5");
        algorithm.reset();
        algorithm.update(password.getBytes());
        byte messageDigest[] = algorithm.digest();
        StringBuffer hexString = new StringBuffer();
        for (int i = 0; i < messageDigest.length; i++) {
            hexString.append(Integer.toHexString(0xFF & messageDigest[i]));
        }
        return hexString.toString();
    } catch (NoSuchAlgorithmException nsae) {
    }
    return null;
}

public static String getMD5(String text) throws NoSuchAlgorithmException, UnsupportedEncodingException {
    MessageDigest md;
    md = MessageDigest.getInstance("MD5");
    byte[] md5hash = new byte[32];
    md.update(text.getBytes("iso-8859-1"), 0, text.length());
    md5hash = md.digest();
    return convertToHex(md5hash);
}

public static String SHA1(String text) throws NoSuchAlgorithmException, UnsupportedEncodingException {
    MessageDigest md;
    md = MessageDigest.getInstance("SHA-1");
    byte[] sha1hash = new byte[40];
    md.update(text.getBytes("iso-8859-1"), 0, text.length());
    sha1hash = md.digest();
    return convertToHex(sha1hash);
}

public static String createHash(String seed) {
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("SHA");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("Can't happen!", e);
    }
    try {
        md.update(seed.getBytes(CHARSET));
        md.update(String.valueOf(System.currentTimeMillis()).getBytes(CHARSET));
        return toHexString(md.digest());
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("Can't happen!", e);
    }
}

public static void copyFile(File source, File dest) throws IOException {
    log.debug("Copy from {} to {}", source.getAbsoluteFile(), dest.getAbsoluteFile());
    FileInputStream fi = new FileInputStream(source);
    FileChannel fic = fi.getChannel();
    MappedByteBuffer mbuf = fic.map(FileChannel.MapMode.READ_ONLY, 0, source.length());
    fic.close();
    fi.close();
    fi = null;
    if (!dest.exists()) {
        String destPath = dest.getPath();
        log.debug("Destination path: {}", destPath);
        String destDir = destPath.substring(0, destPath.lastIndexOf(File.separatorChar));
        log.debug("Destination dir: {}", destDir);
        File dir = new File(destDir);
        if (!dir.exists()) {
            if (dir.mkdirs()) {
                log.debug("Directory created");
            } else {
                log.warn("Directory not created");
            }
        }
        dir = null;
    }
    FileOutputStream fo = new FileOutputStream(dest);
    FileChannel foc = fo.getChannel();
    foc.write(mbuf);
    foc.close();
    fo.close();
    fo = null;
    mbuf.clear();
    mbuf = null;
}

protected static String hashPassword(String password, String salt) throws NoSuchAlgorithmException {
    String s = salt + password;
    MessageDigest md = MessageDigest.getInstance("MD5");
    md.update(s.getBytes());
    byte bs[] = md.digest();
    String s1 = BASE64Encoder.encode(bs);
    return new StringBuffer(salt).append(':').append(s1).toString();
}

private boolean dependencyOutOfDate(ScriptCacheEntry entry) {
    if (entry != null) {
        for (Iterator i = entry.dependencies.keySet().iterator(); i.hasNext(); ) {
            URLConnection urlc = null;
            URL url = (URL) i.next();
            try {
                urlc = url.openConnection();
                urlc.setDoInput(false);
                urlc.setDoOutput(false);
                long dependentLastModified = urlc.getLastModified();
                if (dependentLastModified > ((Long) entry.dependencies.get(url)).longValue()) {
                    return true;
                }
            } catch (IOException ioe) {
                return true;
            }
        }
    }
    return false;
}

public static void cpdir(File src, File dest) throws BrutException {
    dest.mkdirs();
    File[] files = src.listFiles();
    for (int i = 0; i < files.length; i++) {
        File file = files[i];
        File destFile = new File(dest.getPath() + File.separatorChar + file.getName());
        if (file.isDirectory()) {
            cpdir(file, destFile);
            continue;
        }
        try {
            InputStream in = new FileInputStream(file);
            OutputStream out = new FileOutputStream(destFile);
            IOUtils.copy(in, out);
            in.close();
            out.close();
        } catch (IOException ex) {
            throw new BrutException("Could not copy file: " + file, ex);
        }
    }
}

private void copyResource(final String resourceName, final File file) throws IOException {
    assertTrue(resourceName.startsWith("/"));
    InputStream in = null;
    boolean suppressExceptionOnClose = true;
    try {
        in = this.getClass().getResourceAsStream(resourceName);
        assertNotNull("Resource '" + resourceName + "' not found.", in);
        OutputStream out = null;
        try {
            out = new FileOutputStream(file);
            IOUtils.copy(in, out);
            suppressExceptionOnClose = false;
        } finally {
            try {
                if (out != null) {
                    out.close();
                }
            } catch (final IOException e) {
                if (!suppressExceptionOnClose) {
                    throw e;
                }
            }
        }
    } finally {
        try {
            if (in != null) {
                in.close();
            }
        } catch (final IOException e) {
            if (!suppressExceptionOnClose) {
                throw e;
            }
        }
    }
}

