        } catch (Exception e) {
            conn = null;
            listener.connectionIsOk(false, null);
            validPublisher = false;
        }
        if (validPublisher) {
            if (!allNecessaryTablesCreated(conn)) {
                conn = null;
                listener.connectionIsOk(false, null);
                validPublisher = false;
            }
            listener.connectionIsOk(true, conn);
        }
    } else {
        listener.connectionIsOk(false, null);
    }
    return validPublisher;
}

