private static void backupFile(File file) {
    FileChannel in = null, out = null;
    try {
        if (!file.getName().endsWith(".bak")) {
            in = new FileInputStream(file).getChannel();
            out = new FileOutputStream(new File(file.toString() + ".bak")).getChannel();
            long size = in.size();
            MappedByteBuffer buf = in.map(FileChannel.MapMode.READ_ONLY, 0, size);
            out.write(buf);
        }
    } catch (Exception e) {
        e.getMessage();
    } finally {
        try {
            System.gc();
            if (in != null) in.close();
            if (out != null) out.close();
        } catch (Exception e) {
            e.getMessage();
        }
    }
}

private String doExecute(AbortableHttpRequest method) throws Throwable {
    HttpClient client = CLIENT.newInstance();
    HttpResponse rsp = client.execute((HttpUriRequest) method);
    HttpEntity entity = rsp.getEntity();
    if (entity == null) throw new RequestError("No entity in method");
    InputStream in = null;
    try {
        in = entity.getContent();
        BufferedReader reader = new BufferedReader(new InputStreamReader(in));
        StringBuilder inStr = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            inStr.append(line).append("\r\n");
        }
        entity.consumeContent();
        return inStr.toString();
    } catch (IOException ex) {
        LOG.error("IO exception: " + ex.getMessage());
        throw ex;
    } catch (RuntimeException ex) {
        method.abort();
        throw ex;
    } finally {
        if (in != null) in.close();
    }
}

