    try {
        fileReader = new BomStrippingInputStreamReader(url.openStream());
        firstLine = fileReader.readLine();
    } finally {
        if (fileReader != null) fileReader.close();
    }
    if (firstLine == null) {
        return false;
    }
    for (String startOfXml : STARTOFXMLAPPLICATIONFILES) {
