            System.out.println("-----HOST: " + i + ": " + (String) v_delegations_host.elementAt(i));
            System.out.println("-----URL: " + i + ": " + (String) v_delegations_url.elementAt(i));
            System.out.println("-----METHOD: " + i + ": " + (String) v_delegations_method.elementAt(i));
