    URL url = new URL("http://translatewiki.net/w/i.php?title=Special:MessageGroupStats&group=out-osm-site");
    String str = StreamUtil.toString(url.openStream());
    Pattern pattern = Pattern.compile(".*language=([^;\"]+).*");
