public static void copyFile(File src, File dest, int bufSize, boolean force) throws IOException {
    if (dest.exists()) if (force) dest.delete(); else throw new IOException("Cannot overwrite existing file: " + dest.getName());
    byte[] buffer = new byte[bufSize];
    int read = 0;
    InputStream in = null;
    OutputStream out = null;
    try {
        in = new FileInputStream(src);
        out = new FileOutputStream(dest);
        while (true) {
            read = in.read(buffer);
            if (read == -1) break;
            out.write(buffer, 0, read);
        }
    } finally {
        if (in != null) try {
            in.close();
        } finally {
            if (out != null) out.close();
        }
    }
}

static void conditionalCopyFile(File dst, File src) throws IOException {
    if (dst.equals(src)) return;
    if (!dst.isFile() || dst.lastModified() < src.lastModified()) {
        System.out.println("Copying " + src);
        InputStream is = new FileInputStream(src);
        OutputStream os = new FileOutputStream(dst);
        byte[] buf = new byte[8192];
        int len;
        while ((len = is.read(buf)) > 0) os.write(buf, 0, len);
        os.close();
        is.close();
    }
}

