public static String getKeyWithRightLength(final String key, int keyLength) {
    if (keyLength > 0) {
        if (key.length() == keyLength) {
            return key;
        } else {
            MessageDigest md = null;
            try {
                md = MessageDigest.getInstance("SHA-1");
            } catch (NoSuchAlgorithmException e) {
                return "";
            }
            md.update(key.getBytes());
            byte[] hash = md.digest();
            if (keyLength > 20) {
                byte nhash[] = new byte[keyLength];
                for (int i = 0; i < keyLength; i++) {
                    nhash[i] = hash[i % 20];
                }
                hash = nhash;
            }
            return new String(hash).substring(0, keyLength);
        }
    } else {
        return key;
    }
}

public static String toMD5(String seed) {
    MessageDigest md5 = null;
    StringBuffer temp_sb = null;
    try {
        md5 = MessageDigest.getInstance("MD5");
        md5.update(seed.getBytes());
        byte[] array = md5.digest();
        temp_sb = new StringBuffer();
        for (int i = 0; i < array.length; i++) {
            int b = array[i] & 0xFF;
            if (b < 0x10) temp_sb.append('0');
            temp_sb.append(Integer.toHexString(b));
        }
    } catch (NoSuchAlgorithmException err) {
        err.printStackTrace();
    }
    return temp_sb.toString();
}

