                index.index(VUE.getActiveMap());
            }
            FileWriter writer = new FileWriter(file);
            index.write(writer);
            writer.close();
        } else if (name.endsWith(VueUtil.VueArchiveExtension)) {
            Archive.writeArchive(map, file);
