            Log.warn("Unknown save type for filename extension: " + name);
            return false;
        }
        Log.debug("Save completed for " + file);
        if (!VUE.isApplet()) {
            VueFrame frame = (VueFrame) VUE.getMainWindow();
            String title = VUE.getName() + ": " + name;
            frame.setTitle(title);
