                        }
                        segmentFileMaps.add(chunkFiles);
                        fcpOut.flush();
                        fileIn.close();
                    }
                    int checkNo = 0;
                    int checkBlockCount = (int) ((FcpFECUtilsSegmentHeader) segmentHeaders.get(i)).CheckBlockCount;
                    File[] checkFiles = new File[checkBlockCount];
                    File uploadMe = null;
                    FileOutputStream outFile = null;
                    {
                        String currentLine;
