                                outFile.write(buffer);
                                checkPtr += currentRead;
                                if (checkPtr == checkBlockSize) {
                                    outFile.close();
                                    checkFiles[checkNo] = uploadMe;
                                    uploadMe = null;
                                    checkNo++;
                                    checkCnt++;
                                    checkPtr = 0;
                                }
                            }
                        } while (currentLine.length() > 0);
