}

public static void copyFile(File in, File out) throws IOException {
    FileChannel inChannel = new FileInputStream(in).getChannel();
    FileChannel outChannel = new FileOutputStream(out).getChannel();
    try {
        if (System.getProperty("os.name").toUpperCase().indexOf("WIN") != -1) {
            int maxCount = (64 * 1024 * 1024) - (32 * 1024);
            long size = inChannel.size();
            long position = 0;
            while (position < size) {
                position += inChannel.transferTo(position, maxCount, outChannel);
            }
        } else {
            inChannel.transferTo(0, inChannel.size(), outChannel);
        }
    } finally {
        if (inChannel != null) try {
            inChannel.close();
        } catch (Exception e) {
        }
        ;
        if (outChannel != null) try {
            outChannel.close();
        } catch (Exception e) {
        }
        ;
    }
}

public static String retrieveQ(String urlToRetrieve) throws MalformedURLException, IOException {
    URL url = new URL(urlToRetrieve);
    URLConnection uc = url.openConnection();
    InputStream is = uc.getInputStream();
    BufferedReader in = new BufferedReader(new InputStreamReader(is));
    StringBuilder output = new StringBuilder(16384);
    String str;
    boolean first = true;
    while ((str = in.readLine()) != null) {
        if (!first) output.append("\n");
        first = false;
        output.append(str);
    }
    in.close();
    System.err.println(((HttpURLConnection) uc).getResponseMessage());
    return output.toString();
}

protected String doRawRequest(String postData) throws IOException {
    URL url = new URL(SERVICE_URL);
    URLConnection conn = url.openConnection();
    conn.setDoOutput(true);
    OutputStreamWriter wr = new OutputStreamWriter(conn.getOutputStream());
    wr.write(postData);
    wr.flush();
    BufferedReader rd = new BufferedReader(new InputStreamReader(conn.getInputStream()));
    StringBuffer sb = new StringBuffer();
    String line;
    while ((line = rd.readLine()) != null) {
        sb.append(line);
    }
    wr.close();
    rd.close();
    return sb.toString();
}

