                        while (iter1.hasNext()) {
                            rwep = iter1.next();
                            realm = (RealmDb) rwep.realm;
                            psImpl.setInt(1, realm.getRealmId());
                            psImpl.setInt(2, user.userId);
                            psImpl.setInt(3, user.domainId);
                            psImpl.setString(4, rwep.password);
                            psImpl.executeUpdate();
                        }
