        ResultSet rs = related2.executeQuery();
        int[] related_items = new int[5];
        int counter = 0;
        int last = 0;
        while (rs.next()) {
            last = rs.getInt(1);
            related_items[counter] = last;
            counter++;
        }
        for (int i = counter; i < 5; i++) {
            last++;
            related_items[i] = last;
        }
