        in = new BufferedInputStream(new URL(url).openStream());
        out = new BufferedOutputStream(bytearray, 1024);
        byte[] data = new byte[1024];
        int x = 0;
        while ((x = in.read(data, 0, 1024)) >= 0) {
            out.write(data, 0, x);
        }
        return bytearray.toString();
