        try {
            InputStream file = url.openStream();
            if (size == 0) {
                int n = file.available();
                baBuffer = new byte[n - offset];
            }
            DataInputStream dataFile = new DataInputStream(file);
            try {
                dataFile.skip(offset);
                dataFile.readFully(baBuffer);
