            logger.error("IO Error", e);
            throw new ArcImsException("arcims_server_error");
        }
    }
    if (!f.exists()) {
        downloadedFiles.remove(virtualUrl);
        f = doRequestPost(url, req, fName, override);
    }
    return f;
}

