void sort(int a[]) throws Exception {
    int j;
    int limit = a.length;
    int st = -1;
    while (st < limit) {
        boolean flipped = false;
        st++;
        limit--;
        for (j = st; j < limit; j++) {
            if (stopRequested) {
                return;
            }
            if (a[j] > a[j + 1]) {
                int T = a[j];
                a[j] = a[j + 1];
                a[j + 1] = T;
                flipped = true;
                pause(st, limit);
            }
        }
        if (!flipped) {
            return;
        }
        for (j = limit; --j >= st; ) {
            if (stopRequested) {
                return;
            }
            if (a[j] > a[j + 1]) {
                int T = a[j];
                a[j] = a[j + 1];
                a[j + 1] = T;
                flipped = true;
                pause(st, limit);
            }
        }
        if (!flipped) {
            return;
        }
    }
    pause(st, limit);
}

@DeclarePerfMonTimer("SortingTest.bubbleSort")
private void bubbleSort(int values[]) {
    int len = values.length - 1;
    for (int i = 0; i < len; i++) {
        for (int j = 0; j < len - i; j++) {
            if (values[j] > values[j + 1]) {
                int tmp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = tmp;
            }
        }
    }
}

private void downloadThread() {
    int c;
    status = false;
    try {
        URLConnection urlc = resource.url.openConnection();
        File f = resource.createFile();
        boolean resume = false;
        resource.resetBytesDown();
        if (f.exists()) {
            if (f.lastModified() > resource.date.getTime()) {
                if ((resource.getFileSize() == f.length())) {
                    status = true;
                    return;
                } else {
                    urlc.setRequestProperty("Range", "bytes=" + f.length() + "-");
                    resume = true;
                    resource.incrementBytesDown(f.length());
                    System.out.println("Resume download");
                    System.out.println("file length: " + f.length());
                }
            }
        }
        urlc.connect();
        bin = new BufferedInputStream(urlc.getInputStream());
        file_out = new FileOutputStream(f.getPath(), resume);
        while (life) {
            if (bin.available() > 0) {
                c = bin.read();
                if (c == -1) {
                    break;
                }
                file_out.write(c);
                if (resource.incrementBytesDown()) {
                    break;
                } else {
                    continue;
                }
            }
            sleep(WAIT_FOR_A_BYTE_TIME);
        }
        file_out.flush();
        status = true;
    } catch (IOException e) {
        System.out.println("excepcion cpoy file");
    } catch (InterruptedException e) {
        System.out.println("InterruptException download");
        System.out.println(e);
    }
}

