public static String EncryptString(String method, String input) {
    MessageDigest md = null;
    byte[] byteHash = null;
    StringBuffer resultString = new StringBuffer();
    if (method.equals("SHA1") || method.equals("MD5")) {
        try {
            md = MessageDigest.getInstance(method);
        } catch (NoSuchAlgorithmException e) {
            System.out.println("NoSuchAlgorithmException caught!");
            return null;
        }
    } else {
        return null;
    }
    md.reset();
    md.update(input.getBytes());
    byteHash = md.digest();
    for (int i = 0; i < byteHash.length; i++) {
        String tmp = Integer.toHexString(0xff & byteHash[i]);
        if (tmp.length() < 2) tmp = "0" + tmp;
        resultString.append(tmp);
    }
    return (resultString.toString());
}

public static String md5sum(String s, String alg) {
    try {
        MessageDigest md = MessageDigest.getInstance(alg);
        md.update(s.getBytes(), 0, s.length());
        StringBuffer sb = new StringBuffer();
        synchronized (sb) {
            for (byte b : md.digest()) sb.append(pad(Integer.toHexString(0xFF & b), ZERO.charAt(0), 2, true));
        }
        return sb.toString();
    } catch (Exception ex) {
        log(ex);
    }
    return null;
}

