public void run() throws Exception {
    logger.debug("#run enter");
    logger.debug("#run lineId : " + lineId);
    logger.debug("#run quantityNew : " + quantityNew);
    logger.debug("#run priceNew : " + priceNew);
    ResultSet rs = null;
