    try {
        connection.setAutoCommit(false);
        Integer itemId = null;
        Integer quantity = null;
        ps = connection.prepareStatement(SQL_SELECT_ORDER_LINE);
        ps.setInt(1, lineId);
        rs = ps.executeQuery();
        while (rs.next()) {
            itemId = rs.getInt("ITEM_ID");
